import React from 'react';
import { FormattedMessage } from 'react-intl';

import { CopyIcon } from '@dynatrace/strato-icons';

import { Menu } from '../../../../navigation/menu/Menu.js';
import { dataTableMessages } from '../../../DataTable/messages.js';

export type TableUserActionsCopyItemProps = {
  /** The string representation of the cell value that gets copied to the clipboard when the user selects the action item. */
  value: string;
};

/**
 * Configuration component for providing a cell action for copying the cell content.
 * This component can only be used as a child element of `<TableUserActions>`.
 */
export const CopyItem = ({ value }: TableUserActionsCopyItemProps) => {
  return (
    <Menu.Item
      onSelect={() => {
        navigator.clipboard.writeText(value);
      }}
    >
      <Menu.ItemIcon>
        <CopyIcon />
      </Menu.ItemIcon>
      <FormattedMessage {...dataTableMessages.copyItemLabel} />
    </Menu.Item>
  );
};

CopyItem['displayName'] = 'TableUserActions.CopyItem';
